<?php
namespace App\Http\Requests\Admin; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rules\Password;
class StoreUserRequest extends FormRequest { public function authorize(): bool{return true;} public function rules(): array{return ['name'=>['required','string','max:255'],'email'=>['required','email','max:255','unique:users,email'],'phone'=>['nullable','string','max:30'],'username'=>['nullable','string','max:100','unique:users,username'],'password'=>['required','confirmed',Password::min(8)->letters()->numbers()],'role'=>['required','exists:roles,name'],'is_active'=>['required','boolean']];} }
